.document_box{
  position: relative;
  height: 100%;
  .document_list{
    height: calc(100% - 47px);
    overflow: auto;
  }
  .document_list_t{
    padding-top: 60px;
  }


}
.resource_item{
  padding: 0 15px 20px 0;
  border-bottom: 1px solid #f0f0f0;
  margin-bottom: 20px;
  position: relative;
  // height: 165px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  .coverImg{
    height: 140px;
    width: 250px;
    background: #ebe7e7;
    position: absolute;
    left: 0px;
    border-radius: 5px;
    text-align: center;
    border: 1px solid #ebe7e7;
    img{height: 100%;width: 100%;border-radius: 5px;}
  }
  .item_top{
    display: flex;
    align-items: center;
    margin-bottom: 20px;
    .item_tag{
      font-size: 11px;
      color: #1061ff;
      background: #cce4ff;
      display: inline-block;
      padding: 1px 5px;
      border-radius: 2px;
      margin-right: 10px;
      white-space: nowrap;
    }
    img{
      margin-right: 10px;
    }
    .item_title{
      color: #000;
      font-weight: bold;
      font-family: '黑体';
      margin-left: 10px;
      cursor: pointer;
      &:hover{
        color: #1061ff;
      }
    }
  }
  .item_middle{
    background-color: #ecf5ff;
    padding: 10px;
    border-radius: 3px;
    font-size: 14px;
    margin-bottom: 15px;

    // font-size: 14px;
    // margin-bottom: 20px;
    .item_middle_c{
      display: flex;
      align-items: center;

      .line1{
        width: 70px;
        color:#1061ff;
      }
      .line2{
        flex: 1;
        color:#666
      }
    }

    i{
      white-space: nowrap;
      font-style: normal;
    }
    span{
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
      // padding-right: 15px;
    }
  }
  .item_footer{
    display: flex;
    justify-content: space-between;
    align-items: center;
    .footer_left{
      ::v-deep .el-button--mini.is-round{
        padding: 7px 15px!important;
        font-size: 12px;
        height: inherit;
      }
    }
    .footer_right{
      font-size: 14px;
    }
  }
}
::-webkit-scrollbar{
  width: 5px;
  height: 5px;
}
::v-deep ::-webkit-scrollbar-button{
  display: none
}
::-webkit-scrollbar-thumb{
  background: #bed4ff;
  border-radius: 3px
}
::-webkit-scrollbar-track{
  margin: 5px
}
